body {
    font-family: 'Inter', sans-serif;
    font-size: 18px;
    line-height: 1.6; /* Unitless for scalability */
}

@media (max-width: 768px) {
    body {
        font-size: 16px;
        line-height: 1.5; /* Slightly tighter on smaller screens */
    }
}

h1 {
    line-height: 1.1; /* Tighter line-height for headings */
    font-weight: 700;
}
